/* Test driver for the C translation of dsp/ep3_core.genexpr (generated by gx_cgen.py).
 * usage: ep3_run <sr> <infile> <ncols> <names|-> <outfile> [srswitch=N:SR] [param=value ...]
 *   infile : ncols doubles per sample; column 0 is the audio input (fed to in1 and in2),
 *            columns 1.. are per-sample values for the comma-separated parameter names.
 *   outfile: 8 doubles per sample (out1..out8).
 * Prints ns/sample so the same build doubles as a CPU proxy. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "ep3_core_gen.c"
#include "ep3_params.inc"

int main(int argc, char** argv) {
	if (argc < 6) { fprintf(stderr, "usage\n"); return 1; }
	SR = atof(argv[1]);
	const char* inf = argv[2];
	int ncols = atoi(argv[3]);
	char names[4096]; strncpy(names, argv[4], sizeof names - 1); names[sizeof names - 1] = 0;
	const char* outf = argv[5];
	long sw_n = -1; double sw_sr = 0;
	for (int i = 6; i < argc; i++) {
		if (!strncmp(argv[i], "srswitch=", 9)) { sscanf(argv[i] + 9, "%ld:%lf", &sw_n, &sw_sr); continue; }
		if (!set_param(argv[i])) { fprintf(stderr, "bad param %s\n", argv[i]); return 2; }
	}
	char* pn[64]; int np = 0;
	if (strcmp(names, "-")) { char* tok = strtok(names, ","); while (tok && np < 64) { pn[np++] = tok; tok = strtok(NULL, ","); } }
	if (np != ncols - 1) { fprintf(stderr, "ncols/names mismatch\n"); return 3; }
	FILE* fi = fopen(inf, "rb"); FILE* fo = fopen(outf, "wb");
	if (!fi || !fo) { fprintf(stderr, "io\n"); return 4; }
	double row[65], OUT[8], last[64]; char kv[128];
	for (int i = 0; i < 64; i++) last[i] = 1e300;
	long n = 0; struct timespec t0, t1; double el = 0;
	while (fread(row, sizeof(double), ncols, fi) == (size_t)ncols) {
		if (n == sw_n) SR = sw_sr;
		for (int i = 0; i < np; i++) if (row[i + 1] != last[i]) {
			snprintf(kv, sizeof kv, "%s=%.17g", pn[i], row[i + 1]); set_param(kv); last[i] = row[i + 1]; }
		clock_gettime(CLOCK_MONOTONIC, &t0);
		tick(row[0], row[0], OUT);
		clock_gettime(CLOCK_MONOTONIC, &t1);
		el += (t1.tv_sec - t0.tv_sec) + 1e-9 * (t1.tv_nsec - t0.tv_nsec);
		fwrite(OUT, sizeof(double), 8, fo); n++;
	}
	fclose(fi); fclose(fo);
	printf("samples=%ld ns_per_sample=%.1f\n", n, n ? 1e9 * el / n : 0.0);
	return 0;
}
